-- PostgreSQL target schema for CrewUp AI; create on a private managed database.
-- Do not import real user passwords into an untrusted database.
CREATE TABLE IF NOT EXISTS users(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password TEXT NOT NULL,skills TEXT NOT NULL DEFAULT '',city TEXT NOT NULL DEFAULT '',interests TEXT NOT NULL DEFAULT '',avatar TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS events(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,title TEXT,category TEXT,location TEXT,event_date TEXT,description TEXT,cover TEXT,mode TEXT);
CREATE TABLE IF NOT EXISTS crews(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT NOT NULL,description TEXT DEFAULT '',event_id BIGINT REFERENCES events(id),created_by BIGINT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS crew_members(crew_id BIGINT NOT NULL REFERENCES crews(id),user_id BIGINT NOT NULL REFERENCES users(id),role TEXT NOT NULL DEFAULT 'member',joined_at TEXT NOT NULL,PRIMARY KEY(crew_id,user_id));
CREATE TABLE IF NOT EXISTS join_requests(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,crew_id BIGINT NOT NULL REFERENCES crews(id),user_id BIGINT NOT NULL REFERENCES users(id),status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL,UNIQUE(crew_id,user_id));
CREATE TABLE IF NOT EXISTS tasks(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,crew_id BIGINT NOT NULL REFERENCES crews(id),title TEXT NOT NULL,description TEXT DEFAULT '',status TEXT NOT NULL DEFAULT 'todo',priority TEXT NOT NULL DEFAULT 'medium',assignee_id BIGINT REFERENCES users(id),due_date TEXT DEFAULT '',skills TEXT DEFAULT '',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS transfers(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,task_id BIGINT NOT NULL REFERENCES tasks(id),from_user BIGINT NOT NULL REFERENCES users(id),to_user BIGINT NOT NULL REFERENCES users(id),reason TEXT NOT NULL,notes TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'pending_recipient',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS activity(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,crew_id BIGINT NOT NULL REFERENCES crews(id),actor_id BIGINT NOT NULL REFERENCES users(id),action TEXT NOT NULL,detail TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS messages(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,crew_id BIGINT NOT NULL REFERENCES crews(id),user_id BIGINT NOT NULL REFERENCES users(id),body TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS travel_plans(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id),event_id BIGINT NOT NULL REFERENCES events(id),departure_city TEXT NOT NULL,travel_date TEXT NOT NULL,mode TEXT NOT NULL DEFAULT 'Flexible',visibility TEXT NOT NULL DEFAULT 'opt_in',created_at TEXT NOT NULL,UNIQUE(user_id,event_id));
CREATE TABLE IF NOT EXISTS travel_requests(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,from_user BIGINT NOT NULL REFERENCES users(id),to_user BIGINT NOT NULL REFERENCES users(id),event_id BIGINT NOT NULL REFERENCES events(id),status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL,UNIQUE(from_user,to_user,event_id));
CREATE INDEX IF NOT EXISTS idx_tasks_crew_status ON tasks(crew_id,status);
CREATE INDEX IF NOT EXISTS idx_transfers_task_status ON transfers(task_id,status);
CREATE INDEX IF NOT EXISTS idx_travel_event ON travel_plans(event_id);
